  }
}

/**
 * Shared types for the webapp server
 */

export interface AgentrackError {
  result: string;
  message: string;
}

export interface HealthResponse {
  status: "ok";
  tracker: "initialized" | "not_initialized";
}

export interface ApiErrorResponse {
  error: true;
  code: string;
  message: string;
}

import { Tracker } from "agentrack";

/**
 * Singleton Tracker instance.
 *
 * Uses AGENTACK_CWD env var if set, otherwise falls back to process.cwd().
 */
const cwd = process.env.AGENTACK_CWD || process.cwd();

export const tracker = new Tracker(cwd);

import type { Context } from "hono";
import type { AgentrackError, ApiErrorResponse } from "../types.js";

/**
 * Maps agentrack errors to appropriate HTTP responses.
 */
function handleAgentrackError(error: AgentrackError, c: Context) {
  const statusMap: Record<string, number> = {
    NOT_FOUND: 404,
    NOT_INITIALIZED: 500,
    TOKEN_REQUIRED: 403,
    INVALID_TOKEN: 401,
    VALIDATION_ERROR: 400,
  };
  const status = statusMap[error.result] || 500;
  return c.json<ApiErrorResponse>(
    { error: true, code: error.result, message: error.message },
    status
  );
}

/**
 * Global error handler middleware for the Hono app.
 * Catches agentrack errors and maps them to HTTP responses.
 */
export function errorHandler(err: Error, c: Context) {
  console.error(`[Error] ${err.message}`);

  // Check if it's an agentrack error (has result property)
  const agentrackError = err as AgentrackError & Error;
  if (agentrackError.result) {
    return handleAgentrackError(agentrackError, c);
  }

  return c.json<ApiErrorResponse>(
    { error: true, code: "INTERNAL_ERROR", message: err.message },
    500
  );
}

import { Hono } from "hono";
import { tracker } from "../utils/tracker.js";
import type { HealthResponse } from "../types.js";

const health = new Hono();

health.get("/", (c) => {
  let trackerStatus: "initialized" | "not_initialized" = "not_initialized";

  try {
    // Check if agentrack is initialized by attempting to access the worktree
    const initialized = tracker.isWorktreeInitialized();
    trackerStatus = initialized ? "initialized" : "not_initialized";
  } catch {
    trackerStatus = "not_initialized";
  }

  return c.json<HealthResponse>({
    status: "ok",
    tracker: trackerStatus,
  });
});

export default health;

import { Hono } from "hono";
import { cors } from "hono/cors";
import { logger } from "hono/logger";
import { serveStatic } from "hono/bun";
import { errorHandler } from "./middleware/error-handler.js";
import healthRoute from "./routes/health.js";

const app = new Hono();

// Middleware
app.use("/api/*", cors());
app.use("/api/*", logger());

// API routes
app.route("/api/health", healthRoute);

// Serve frontend static files (production)
app.use("/*", serveStatic({ root: "./frontend/dist" }));

// Global error handler
app.onError(errorHandler);

const port = parseInt(process.env.PORT || "3000", 10);
console.log(`Server running on http://localhost:${port}`);

export default {
  port,
  fetch: app.fetch,
};

